        ///  `mxc_sandbox_take_stdout` / `mxc_sandbox_take_stderr` call.
        /// </summary>
        [DllImport(__DllName, EntryPoint = "mxc_read_stream_free", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
        internal static extern void mxc_read_stream_free(MxcReadStream* stream);

        /// <summary>
        ///  Free a writable (stdin) stream handle, closing stdin and sending EOF to the
        ///  child. Safe to call with null (no-op). Must be called exactly once.
        ///
        ///  # Safety
        ///  `stream` must be null or a live, not-yet-freed handle from
        ///  [`mxc_sandbox_take_stdin`].
        /// </summary>
        [DllImport(__DllName, EntryPoint = "mxc_write_stream_free", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
        internal static extern void mxc_write_stream_free(MxcWriteStream* stream);

        /// <summary>
        ///  Free a stream-closer handle. Safe to call with null (no-op). Must be called
        ///  exactly once and not concurrently with [`mxc_stream_closer_close`].
        ///
        ///  # Safety
        ///  `closer` must be null or a live, not-yet-freed handle from
        ///  [`mxc_sandbox_stdout_closer`] / [`mxc_sandbox_stderr_closer`].
        /// </summary>
        [DllImport(__DllName, EntryPoint = "mxc_stream_closer_free", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
        internal static extern void mxc_stream_closer_free(MxcStreamCloser* closer);

        /// <summary>
        ///  Run a state-aware lifecycle request (envelope phases) and capture the
        ///  response-envelope JSON.
        ///
        ///  Parses `request_json_utf8` (the wire-format request, with a `phase` field),
        ///  runs the requested phase, and writes the outcome into `*out`. A non-dry-run
        ///  `exec` produces no envelope and is rejected here — run it through
        ///  [`mxc_state_aware_exec_attached`] to attach the workload to this process's
        ///  stdio, or [`mxc_state_aware_exec`] to drive the pipes directly.
        ///
        ///  Returns the resulting status code (also stored in `out-&gt;status`). Returns
        ///  [`MXC_STATUS_NULL_ARGUMENT`] **without running the phase** if `out` is null:
        ///  the caller has nowhere to receive a sandbox id, so provisioning one would
        ///  strand it — nothing else can reclaim a sandbox whose only handle was
        ///  discarded. [`mxc_state_aware_exec`] checks its out-parameter first for the
        ///  same reason.
        ///
        ///  `experimental` is non-zero to opt in to Windows Sandbox; with zero that
        ///  backend is refused with `backend_unavailable` before any work is done.
        ///
        ///  # Safety
        ///  - `request_json_utf8` must be null or a valid NUL-terminated UTF-8 C string.
        ///  - `out` must be null or point to writable [`MxcStateAwareResult`]-sized storage.
        ///  - On success the caller must release `*out` with [`mxc_state_aware_result_free`].
        /// </summary>
        [DllImport(__DllName, EntryPoint = "mxc_state_aware", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
        internal static extern int mxc_state_aware(byte* request_json_utf8, int dry_run, int experimental, MxcStateAwareResult* @out);

        /// <summary>
        ///  Free the owned out-strings of an [`MxcStateAwareResult`] produced by
        ///  [`mxc_state_aware`]. Idempotent; the struct itself is caller-owned.
        ///
        ///  # Safety
        ///  `r` must be null or point to a result previously filled by [`mxc_state_aware`],
        ///  not already freed.
        /// </summary>
        [DllImport(__DllName, EntryPoint = "mxc_state_aware_result_free", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
        internal static extern void mxc_state_aware_result_free(MxcStateAwareResult* r);

        /// <summary>
        ///  Run the `exec` phase of a state-aware request as a **live streaming** process.
        ///
        ///  Parses `request_json_utf8` (an `exec`-phase request with a `sandboxId`),
        ///  spawns the process, and on success writes an opaque
        ///  [`MxcSandbox`](crate::MxcSandbox) handle to `*out_handle` (drive it with the
        ///  `mxc_stream_*` / `mxc_sandbox_*` externs, free it with `mxc_sandbox_free`).
        ///  On failure returns the status code and, if `out_error` is non-null, fills it
        ///  with the message plus the failing API call when there was one (release it
        ///  with [`mxc_error_detail_free`](crate::mxc_error_detail_free));
        ///  `*out_handle` is set to null.
        ///
        ///  `experimental` opts in to Windows Sandbox, as for [`mxc_state_aware`].
        ///  IsolationSession and WSLc require no runtime experimental opt-in.
        ///
        ///  # Safety
        ///  - `request_json_utf8` must be null or a valid NUL-terminated UTF-8 C string.
        ///  - `out_handle` must be non-null and point to writable pointer-sized storage
        ///    holding **no live handle** — it is overwritten with null before anything
        ///    else, and `mxc_sandbox_free` is the handle's only destructor, so free an
        ///    existing one before reusing its storage. On success the caller owns
        ///    `*out_handle` and frees it with `mxc_sandbox_free`.
        ///  - `out_error` must be null, or point to writable storage for one
        ///    [`MxcErrorDetail`] that holds **no live detail**: either fresh or
        ///    uninitialised storage, or storage already released with
        ///    [`mxc_error_detail_free`](crate::mxc_error_detail_free). This function
        ///    overwrites that storage without freeing what was there, so handing it a
        ///    populated detail leaks that detail's strings.
        /// </summary>
        [DllImport(__DllName, EntryPoint = "mxc_state_aware_exec", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
        internal static extern int mxc_state_aware_exec(byte* request_json_utf8, int experimental, MxcSandbox** out_handle, MxcErrorDetail* out_error);

        /// <summary>
        ///  Run a state-aware `exec` **attached to this process's stdio**, blocking until
        ///  the sandboxed process exits.
        ///
        ///  The backend relays the workload's output onto this process's stdout and
        ///  stderr; on IsolationSession it also forwards stdin and allocates a
        ///  pseudo-console, which merges the sandbox's stderr into its stdout.
        ///
        ///  **This process's stdout and stdin must both be terminals**, or the call is
        ///  refused with
        ///  [`MXC_STATUS_MALFORMED_REQUEST`](crate::MXC_STATUS_MALFORMED_REQUEST) and
        ///  nothing is run.
        ///
        ///  Returns `0` on success, with `*out_outcome` filled. On failure returns an
        ///  `MXC_STATUS_*` code and fills `*out_error` if it is non-null.
        ///
        ///  # Safety
        ///  - `request_json_utf8` must be null or a valid NUL-terminated UTF-8 C string.
        ///  - `out_outcome` must point to writable [`MxcExecOutcome`]-sized storage. It
        ///    is checked **before** the workload runs: an attached exec has real side
        ///    effects, and with nowhere to report the outcome the caller could not tell
        ///    what happened.
        ///  - `out_error` must be null, or point to writable storage for one
        ///    [`MxcErrorDetail`] that holds **no live detail** — see
        ///    [`mxc_state_aware_exec`] for why.
        ///  - Nothing here is owned by the caller except `*out_error`, released with
        ///    [`mxc_error_detail_free`](crate::mxc_error_detail_free).
        /// </summary>
        [DllImport(__DllName, EntryPoint = "mxc_state_aware_exec_attached", CallingConvention = CallingConvention.Cdecl, ExactSpelling = true)]
        internal static extern int mxc_state_aware_exec_attached(byte* request_json_utf8, int experimental, MxcExecOutcome* out_outcome, MxcErrorDetail* out_error);


    }

    /// <summary>
    ///  The result of an [`mxc_run_request`] call.
    ///
    ///  On success (`status == 0`), `exit_code` / `timed_out` describe how the
    ///  process finished and `stdout_utf8` / `stderr_utf8` carry its captured output
    ///  (every field of `error` is null). On failure, `error` carries the message
    ///  and, when an API call was in flight, which call failed and with what
    ///  platform status; the output fields are null.
    ///
    ///  All non-null pointers — including those inside `error` — are owned by the
    ///  caller and must be released with [`mxc_run_result_free`].
    /// </summary>
    [StructLayout(LayoutKind.Sequential)]
    internal unsafe partial struct MxcRunResult
    {
        /// <summary>
        ///  `0` on success; otherwise one of the `MXC_STATUS_*` codes.
        /// </summary>
        public int status;
        /// <summary>
        ///  The process exit code (valid when `status == 0` and `timed_out == 0`).
        /// </summary>
        public int exit_code;
        /// <summary>
        ///  `1` if the run hit its `scriptTimeout` and was killed, else `0`.
        /// </summary>
        public int timed_out;
        /// <summary>
        ///  Captured stdout (UTF-8, NUL-terminated), or null.
        /// </summary>
        public byte* stdout_utf8;
        /// <summary>
        ///  Captured stderr (UTF-8, NUL-terminated), or null.
        /// </summary>
        public byte* stderr_utf8;
        /// <summary>
        ///  Why the call failed, when `status != 0`; all-null otherwise.
        /// </summary>
        public MxcErrorDetail error;
        /// <summary>
        ///  Structured output metadata JSON (UTF-8, NUL-terminated), or null.
        /// </summary>
        public byte* output_metadata_json_utf8;
        /// <summary>
        ///  Security warnings raised during the run, as a JSON array of strings
        ///  (UTF-8, NUL-terminated), or null when the run raised none.
        ///
        ///  A policy that relaxes containment raises one — notably
        ///  `permissiveLearningMode`, which disables deny-by-default. They are not
        ///  written to the host's stderr, so this field is the only way an FFI
        ///  caller sees them.
        /// </summary>
        public byte* warnings_json_utf8;
    }

    /// <summary>
    ///  Why a call failed: the message, plus the failing API call when one was in
    ///  flight.
    ///
    ///  Every non-null field is owned by the caller and must be released — by
    ///  [`mxc_error_detail_free`] when the detail stands alone, or by the owning
    ///  result's free function when it is embedded in one.
    /// </summary>
    [StructLayout(LayoutKind.Sequential)]
    internal unsafe partial struct MxcErrorDetail
    {
        /// <summary>
        ///  Human-readable message (UTF-8, NUL-terminated), or null on success.
        /// </summary>
        public byte* message_utf8;
        /// <summary>
        ///  The API call that failed, namespaced by its interface and free of call
        ///  parameters, so it can be grouped in telemetry. Null when the failure was
        ///  raised before any API call, as a malformed request is.
        /// </summary>
        public byte* operation_utf8;
        /// <summary>
        ///  The underlying platform status, e.g. `0x80070490`. Null when the failure
        ///  carries none.
        /// </summary>
        public byte* native_code_utf8;
        /// <summary>
        ///  An actionable hint, when the failure carries one. Null otherwise.
        /// </summary>
        public byte* remediation_utf8;
    }

